function decodeAsset(value) {
  
  if (typeof value === "string" && value.startsWith("b64:")) {
    const bin = atob(value.slice(4));
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }
  return value;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    let path = url.pathname;

    if (path !== "/" && path.endsWith("/")) path = path.slice(0, -1);

    const asset = ASSETS[path] || ASSETS["/"];
    const headers = {
      "Content-Type": asset.type,
      "Cache-Control": asset.cache,
      "X-Content-Type-Options": "nosniff",
    };

    
    
    
    if (env && env.ASSETS) {
      const res = await env.ASSETS.fetch(new URL(path, url.origin));
      if (res.ok) {
        const h = new Headers(res.headers);
        h.set("Content-Type", asset.type);
        h.set("Cache-Control", asset.cache);
        h.set("X-Content-Type-Options", "nosniff");
        return new Response(res.body, { status: 200, headers: h });
      }
    }

    
    const inline = ASSETS_JSON[asset.file];
    if (inline !== undefined) {
      let body = decodeAsset(inline);
      const rHeaders = new Headers(headers);

      
      const range = request.headers.get("Range");
      if (range && typeof body === "object" && body instanceof Uint8Array) {
        const total = body.byteLength;
        const match = /bytes=(\d*)-(\d*)/.exec(range);
        if (match && total > 0 && !(match[1] === "" && match[2] === "")) {
          let start = 0;
          let end = total - 1;
          if (match[1] === "" && match[2] !== "") {
            
            start = Math.max(total - parseInt(match[2], 10), 0);
          } else {
            start = parseInt(match[1], 10);
            if (match[2] !== "") end = parseInt(match[2], 10);
          }
          if (isNaN(start)) start = 0;
          if (isNaN(end) || end >= total) end = total - 1;
          if (start > end || start >= total) {
            return new Response(null, { status: 416, headers: { "Content-Range": `bytes */${total}` } });
          }
          const chunk = body.slice(start, end + 1);
          rHeaders.set("Content-Range", `bytes ${start}-${end}/${total}`);
          rHeaders.set("Accept-Ranges", "bytes");
          rHeaders.set("Content-Length", String(chunk.byteLength));
          return new Response(chunk, { status: 206, headers: rHeaders });
        }
      }

      if (typeof body === "object" && body instanceof Uint8Array) {
        rHeaders.set("Accept-Ranges", "bytes");
        rHeaders.set("Content-Length", String(body.byteLength));
      }
      return new Response(body, { status: 200, headers: rHeaders });
    }

    return new Response("Seedling Kenya — not found", { status: 404, headers: { "Content-Type": "text/plain" } });
  },
};

 
